map.string:
default
{
    touch_start(integer total_number)
    {
        llSay(0, "Touched by " + llDetectedName(0) + ".");
    }
}

integer CHANNEL = 7;

default
{
    state_entry()
    {
        llListen(CHANNEL, "", NULL_KEY, "");
    }

    listen(integer channel, string name, key id, string message)
    {
        llOwnerSay(name + " said: " + message);
    }
}

default
{
    state_entry()
    {
        llSetTimerEvent(1.0);
    }

    timer()
    {
        llSetText((string)llGetUnixTime(), <1.0, 1.0, 1.0>, 1.0);
    }
}

list BUTTONS = ["Red", "Green", "Blue"];
integer gListen;

stopListening()
{
    llListenRemove(gListen);
    llSetTimerEvent(0.0);
}

default
{
    touch_start(integer total_number)
    {
        key toucher = llDetectedKey(0);
        stopListening();
        integer channel = -1 - (integer)llFrand(1000000.0);
        gListen = llListen(channel, "", toucher, "");
        llDialog(toucher, "Choose a colour.", BUTTONS, channel);
        llSetTimerEvent(30.0);
    }

    listen(integer channel, string name, key id, string message)
    {
        stopListening();
        if (message == "Red") llSetColor(<1.0, 0.0, 0.0>, ALL_SIDES);
        else if (message == "Green") llSetColor(<0.0, 1.0, 0.0>, ALL_SIDES);
        else if (message == "Blue") llSetColor(<0.0, 0.0, 1.0>, ALL_SIDES);
    }

    timer()
    {
        stopListening();
    }
}

default
{
    state_entry()
    {
        llSensorRepeat("", NULL_KEY, AGENT, 20.0, PI, 5.0);
    }

    sensor(integer detected)
    {
        integer i;
        for (i = 0; i < detected; ++i)
        {
            float away = llVecDist(llGetPos(), llDetectedPos(i));
            llOwnerSay(llDetectedName(i) + " is " + (string)llRound(away) + " m away.");
        }
    }

    no_sensor()
    {
        llOwnerSay("Nobody near.");
    }
}

key gRequest;

default
{
    touch_start(integer total_number)
    {
        gRequest = llHTTPRequest("https://example.com/", [HTTP_METHOD, "GET"], "");
    }

    http_response(key request_id, integer status, list metadata, string body)
    {
        if (request_id == gRequest)
        {
            llOwnerSay("HTTP " + (string)status + ": " + llGetSubString(body, 0, 200));
        }
    }
}

string NOTECARD = "config";
integer gLine;
key gQuery;

default
{
    state_entry()
    {
        if (llGetInventoryType(NOTECARD) == INVENTORY_NOTECARD)
        {
            gQuery = llGetNotecardLine(NOTECARD, gLine);
        }
        else
        {
            llOwnerSay("No notecard called " + NOTECARD + " in this object.");
        }
    }

    dataserver(key query_id, string data)
    {
        if (query_id != gQuery)
        {
            return;
        }
        if (data == EOF)
        {
            llOwnerSay("Read " + (string)gLine + " lines.");
            return;
        }
        llOwnerSay(data);
        ++gLine;
        gQuery = llGetNotecardLine(NOTECARD, gLine);
    }

    changed(integer change)
    {
        if (change & CHANGED_INVENTORY)
        {
            llResetScript();
        }
    }
}
